def best_circular_selection(values, k):
    n = len(values)

    if k == 0:
        return 0

    # A single element is not adjacent to itself.
    if n == 1:
        if k == 1:
            return values[0]
        raise ValueError("No valid selection of exactly k elements")

    if k > n // 2:
        raise ValueError("No valid selection of exactly k elements")

    def best_linear(items):
        """Maximum sum of exactly k nonadjacent elements on a line."""
        # None represents an impossible state.
        # prev1[j]: best sum using the previous prefix.
        # prev2[j]: best sum using the prefix two steps back.
        prev2 = [0] + [None] * k
        prev1 = [0] + [None] * k

        for length, value in enumerate(items, start=1):
            current = prev1.copy()  # Skip this element.

            for j in range(1, min(k, (length + 1) // 2) + 1):
                base = prev2[j - 1]
                if base is not None:
                    candidate = base + value
                    if current[j] is None or candidate > current[j]:
                        current[j] = candidate

            prev2, prev1 = prev1, current

        result = prev1[k]
        assert result is not None  # Guaranteed by the feasibility check.
        return result

    # Every valid circular selection excludes at least one endpoint.
    return max(
        best_linear(values[:-1]),  # Exclude the last element.
        best_linear(values[1:]),   # Exclude the first element.
    )

def max_sessions(intervals, gap):
    """Return the maximum number of sessions with the required idle gap."""
    count = 0
    next_available = 0

    for start, end in sorted(intervals, key=lambda interval: interval[1]):
        if start >= next_available:
            count += 1
            next_available = end + gap

    return count

def smallest_balanced(s: str) -> str:
    n = len(s)
    if n % 2:
        raise ValueError("No balanced replacement exists")

    # A balanced string must contain exactly n // 2 opening parentheses.
    opens_needed = n // 2 - s.count("(")
    if not 0 <= opens_needed <= s.count("?"):
        raise ValueError("No balanced replacement exists")

    result = list(s)
    balance = 0

    for i, ch in enumerate(result):
        if ch == "?":
            if opens_needed:
                ch = "("
                opens_needed -= 1
            else:
                ch = ")"
            result[i] = ch

        balance += 1 if ch == "(" else -1
        if balance < 0:
            raise ValueError("No balanced replacement exists")

    return "".join(result)

def longest_spaced_repeat(s: str, gap: int) -> int:
    n = len(s)
    dp = [0] * n
    best = 0

    for i in range(n):
        # Descending order preserves the previous row's dp[j - 1].
        for j in range(n - 1, i, -1):
            if s[i] == s[j]:
                dp[j] = dp[j - 1] + 1
                candidate = min(dp[j], j - i - gap)
                if candidate > best:
                    best = candidate
            else:
                dp[j] = 0

    return best

def min_insertions(s, allowed):
    allowed = set(allowed)
    n = len(s)

    if n < 2:
        return 0

    # Any feasible solution needs at most n - 1 insertions.
    INF = n + 1

    # dp[i][j]: minimum insertions for s[i:j+1], or INF if impossible.
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if s[i] == s[j]:
                # Matching endpoints need no inserted counterparts.
                dp[i][j] = dp[i + 1][j - 1] if length > 2 else 0
            else:
                best = INF

                # Match s[i] by inserting its counterpart after s[j].
                if s[i] in allowed:
                    best = min(best, 1 + dp[i + 1][j])

                # Match s[j] by inserting its counterpart before s[i].
                if s[j] in allowed:
                    best = min(best, 1 + dp[i][j - 1])

                dp[i][j] = best

    answer = dp[0][n - 1]
    return -1 if answer == INF else answer

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)

    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        if node in visited:
            return

        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)

        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        visit(node)

    return order

import re

def compute_balances(transactions):
    balances = {}

    for tx in transactions:
        amount = tx["amount"]
        if (
            not isinstance(amount, str)
            or re.fullmatch(r"[0-9]+(?:\.[0-9]{1,2})?", amount) is None
        ):
            raise ValueError("invalid amount")

        whole, _, fraction = amount.partition(".")
        cent_digits = whole + fraction.ljust(2, "0")

        # Parse directly, without floating point or integer-string size limits.
        cents = 0
        for digit in cent_digits:
            cents = cents * 10 + (ord(digit) - ord("0"))

        if cents <= 0:
            raise ValueError("amount must be positive")

        sender = tx["from"]
        receiver = tx["to"]
        balances[sender] = balances.get(sender, 0) - cents
        balances[receiver] = balances.get(receiver, 0) + cents

    return balances

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])

    # Check conflicts before range validity, as in the original.
    previous_start = None
    deletion_end = None
    for start, delete, insert in ordered:
        if start == previous_start:
            raise ValueError("conflicting hunks")

        # Pure insertions have empty delete ranges.
        if delete > 0:
            if deletion_end is not None and start < deletion_end:
                raise ValueError("conflicting hunks")
            deletion_end = start + delete

        previous_start = start

    for start, delete, insert in ordered:
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")

    # Read only from the original document, so edits cannot shift
    # the coordinates of subsequent hunks.
    result = []
    cursor = 0
    for start, delete, insert in ordered:
        if start > cursor:
            result.extend(lines[cursor:start])
        result.extend(insert)
        cursor = max(cursor, start + delete)

    result.extend(lines[cursor:])
    return result

