            return True
        return False

class CountingBag:
    def __init__(self):
        self._counts = {}
        self._total = 0

    def add(self, item) -> int:
        new_count = self._counts.get(item, 0) + 1
        self._counts[item] = new_count
        self._total += 1
        return new_count

    def discard(self, item) -> bool:
        current = self._counts.get(item, 0)
        if current == 0:
            return False

        if current == 1:
            del self._counts[item]
        else:
            self._counts[item] = current - 1

        self._total -= 1
        return True

    def count(self, item) -> int:
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        return self._total

    def distinct(self) -> int:
        return len(self._counts)

    def most_common(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []

        # Stable sort: equal counts retain dictionary insertion order.
        ranked = sorted(
            self._counts.items(),
            key=lambda pair: pair[1],
            reverse=True,
        )
        return ranked[:k]

