class TTLCache:
    def __init__(self, capacity):
        if (
            not isinstance(capacity, int)
            or isinstance(capacity, bool)
            or capacity < 1
        ):
            raise ValueError("capacity must be an integer >= 1")

        self._capacity = capacity
        # Ordered from least-recently-used to most-recently-used.
        # Each entry is (value, expiration_time).
        self._entries = OrderedDict()
        self._stats = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0,
        }

    def _purge(self, now):
        expired_keys = [
            key
            for key, (_, expires_at) in self._entries.items()
            if expires_at is not None and now >= expires_at
        ]
        for key in expired_keys:
            del self._entries[key]
            self._stats["expirations"] += 1

    def put(self, key, value, now, ttl=None):
        # Validate before purging or changing any state.
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive or None")

        self._purge(now)
        expires_at = None if ttl is None else now + ttl

        if key in self._entries:
            self._entries[key] = (value, expires_at)
            self._entries.move_to_end(key)
            return

        if len(self._entries) == self._capacity:
            self._entries.popitem(last=False)
            self._stats["evictions"] += 1

        self._entries[key] = (value, expires_at)

    def get(self, key, now):
        self._purge(now)

        if key not in self._entries:
            self._stats["misses"] += 1
            return None

        self._stats["hits"] += 1
        self._entries.move_to_end(key)
        return self._entries[key][0]

    def stats(self):
        # Prevent callers from mutating the internal counters.
        return self._stats.copy()

    def __len__(self):
        # No purge: entries count until a put/get removes them.
        return len(self._entries)

class Leaderboard:
    def __init__(self):
        # player -> (best score, sequence of improving submission)
        self._players = {}
        self._sequence = 0

    def submit(self, player, score: int) -> bool:
        current = self._players.get(player)
        if current is not None and score <= current[0]:
            return False  # Leave all state, including tie order, unchanged.

        self._players[player] = (score, self._sequence)
        self._sequence += 1
        return True

    def best(self, player) -> int:
        return self._players[player][0]  # Raises KeyError if unknown.

    def rank(self, player) -> int:
        score = self.best(player)
        return 1 + sum(
            best_score > score
            for best_score, _ in self._players.values()
        )

    def top(self, k: int) -> list:
        if k < 0:
            raise ValueError("k must be nonnegative")
        if k == 0:
            return []

        ordered = sorted(
            self._players.items(),
            key=lambda item: (-item[1][0], item[1][1]),
        )
        return [(player, score) for player, (score, _) in ordered[:k]]

    def player_count(self) -> int:
        return len(self._players)

class IntervalSet:
    def __init__(self) -> None:
        self._intervals: list[tuple[int, int]] = []

    @staticmethod
    def _validate(lo: int, hi: int) -> None:
        if lo >= hi:
            raise ValueError("expected lo < hi")

    def add(self, lo: int, hi: int) -> None:
        self._validate(lo, hi)
        intervals = self._intervals
        n = len(intervals)

        # Skip intervals strictly before the new range.
        # Equality is not skipped because touching intervals must merge.
        i = 0
        while i < n and intervals[i][1] < lo:
            i += 1

        # Merge every overlapping or touching interval.
        j = i
        while j < n and intervals[j][0] <= hi:
            lo = min(lo, intervals[j][0])
            hi = max(hi, intervals[j][1])
            j += 1

        self._intervals = intervals[:i] + [(lo, hi)] + intervals[j:]

    def remove(self, lo: int, hi: int) -> None:
        self._validate(lo, hi)
        result = []

        for a, b in self._intervals:
            if b <= lo or a >= hi:
                result.append((a, b))
                continue

            # Keep any portions outside the removed range.
            if a < lo:
                result.append((a, lo))
            if b > hi:
                result.append((hi, b))

        self._intervals = result

    def contains(self, x: int) -> bool:
        # Find the rightmost interval whose start is <= x.
        left, right = 0, len(self._intervals)
        while left < right:
            mid = (left + right) // 2
            if self._intervals[mid][0] <= x:
                left = mid + 1
            else:
                right = mid

        return left > 0 and x < self._intervals[left - 1][1]

    def total(self) -> int:
        return sum(hi - lo for lo, hi in self._intervals)

    def intervals(self) -> list[tuple[int, int]]:
        # Return a copy so callers cannot mutate the internal list.
        return self._intervals.copy()

    def gaps(self, lo: int, hi: int) -> list[tuple[int, int]]:
        self._validate(lo, hi)
        result = []
        cursor = lo

        for a, b in self._intervals:
            if b <= cursor:
                continue
            if a >= hi:
                break

            if cursor < a:
                result.append((cursor, a))

            cursor = max(cursor, b)
            if cursor >= hi:
                break

        if cursor < hi:
            result.append((cursor, hi))

        return result

