class TaskScheduler:
    """Task IDs must be hashable; priorities must be integers."""

    def __init__(self):
        # Entries: (-priority, submission_order, version, task_id)
        self._heap = []

        # task_id -> (priority, submission_order, version)
        self._active = {}

        self._submission_order = count()
        self._versions = count()

    def submit(self, task_id, priority) -> None:
        if task_id in self._active:
            raise ValueError(f"Task is already active: {task_id!r}")

        order = next(self._submission_order)
        version = next(self._versions)
        self._active[task_id] = (priority, order, version)

        heapq.heappush(self._heap, (-priority, order, version, task_id))
        self._maybe_compact()

    def reprioritize(self, task_id, priority) -> None:
        old_priority, order, _ = self._active[task_id]  # Raises KeyError.

        if priority == old_priority:
            return

        version = next(self._versions)
        self._active[task_id] = (priority, order, version)

        heapq.heappush(self._heap, (-priority, order, version, task_id))
        self._maybe_compact()

    def cancel(self, task_id) -> None:
        del self._active[task_id]  # Raises KeyError.
        self._maybe_compact()

    def pop(self):
        if not self._active:
            raise IndexError("pop from empty TaskScheduler")

        self._discard_stale_entries()
        _, _, _, task_id = heapq.heappop(self._heap)
        del self._active[task_id]

        self._maybe_compact()
        return task_id

    def peek(self):
        if not self._active:
            raise IndexError("peek from empty TaskScheduler")

        self._discard_stale_entries()
        return self._heap[0][3]

    def priority_of(self, task_id) -> int:
        return self._active[task_id][0]  # Raises KeyError.

    def __len__(self) -> int:
        return len(self._active)

    def _discard_stale_entries(self) -> None:
        while self._heap:
            neg_priority, order, version, task_id = self._heap[0]
            current = self._active.get(task_id)

            if current == (-neg_priority, order, version):
                return

            heapq.heappop(self._heap)

    def _maybe_compact(self) -> None:
        # Bound memory even if cancelled or outdated entries never reach
        # the top of the heap.
        if not self._active:
            self._heap.clear()
        elif len(self._heap) > 2 * len(self._active) + 64:
            self._heap = [
                (-priority, order, version, task_id)
                for task_id, (priority, order, version)
                in self._active.items()
            ]
            heapq.heapify(self._heap)

class UndoStack:
    def __init__(self):
        self._values = []
        self._history = []

    def push(self, x) -> None:
        self._values.append(x)
        self._history.append(("push", None))

    def pop(self):
        # If empty, list.pop raises IndexError before history is changed.
        value = self._values.pop()
        self._history.append(("pop", value))
        return value

    def peek(self):
        # Raises IndexError if empty; never changes history.
        return self._values[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")

        operation, value = self._history.pop()
        if operation == "push":
            self._values.pop()
        else:
            self._values.append(value)

    def __len__(self) -> int:
        return len(self._values)

from copy import deepcopy


class VersionedKV:
    def __init__(self):
        self._working = {}
        self._snapshots = []

    @staticmethod
    def _copy_state(state):
        # Preserve the original keys, including identity-based keys.
        # Copy values together to preserve shared references among them.
        values = deepcopy(list(state.values()))
        return dict(zip(state.keys(), values))

    def _validate_version(self, version, minimum):
        if not isinstance(version, int) or not (
            minimum <= version <= self.latest()
        ):
            raise ValueError(f"Invalid version: {version!r}")

    def set(self, key, value) -> None:
        self._working[key] = value

    def delete(self, key) -> None:
        del self._working[key]  # Raises KeyError if absent.

    def get(self, key):
        return self._working[key]  # Raises KeyError if absent.

    def has(self, key) -> bool:
        return key in self._working

    def commit(self) -> int:
        snapshot = self._copy_state(self._working)
        self._snapshots.append(snapshot)
        return self.latest()

    def get_at(self, key, version):
        self._validate_version(version, minimum=1)
        # Return a copy so callers cannot mutate a committed value.
        return deepcopy(self._snapshots[version - 1][key])

    def rollback(self, version) -> None:
        self._validate_version(version, minimum=0)
        self._working = (
            {} if version == 0
            else self._copy_state(self._snapshots[version - 1])
        )

    def latest(self) -> int:
        return len(self._snapshots)

import unicodedata


def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0:
        return ""

    units = 0
    for i, ch in enumerate(s):
        is_mark = unicodedata.category(ch) in {"Mn", "Mc", "Me"}

        # The first code point starts a unit, even if it is a mark.
        # Every subsequent non-mark starts another unit.
        if i == 0 or not is_mark:
            if units == width:
                return s[:i]
            units += 1

    return s

def chunk_evenly(items, n: int) -> list[list]:
    if n < 1:
        raise ValueError("n must be at least 1")

    values = list(items)  # Consume the iterable once.
    size, extra = divmod(len(values), n)

    chunks = []
    start = 0
    for i in range(n):
        end = start + size + (i < extra)
        chunks.append(values[start:end])
        start = end

    return chunks

def kth_root_floor(n: int, k: int) -> int:
    if n < 0 or k < 1:
        raise ValueError("n must be nonnegative and k must be positive")

    if k == 1 or n <= 1:
        return n

    bits = n.bit_length()

    # If k >= bits, then 2**k >= 2**bits > n,
    # so the root is strictly less than 2.
    if k >= bits:
        return 1

    lo = 1
    hi = 1 << ((bits + k - 1) // k)

    # Maintain lo**k <= n < hi**k.
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid

    return lo

from collections import deque

def round_robin(iterables: list) -> "iterator":
    active = deque(iter(source) for source in iterables)

    while active:
        current = active.popleft()
        try:
            value = next(current)
        except StopIteration:
            continue

        active.append(current)
        yield value

from math import fsum

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")

    if any(weight < 0 for weight in weights):
        raise ValueError("weights must be nonnegative")

    total = fsum(weights)
    if not total > 0:
        raise ValueError("total weight must be positive")

    # Exclude zero-weight entries so they can never affect the result,
    # even when the tolerance exceeds half the total weight.
    pairs = sorted(
        ((value, weight) for value, weight in zip(values, weights)
         if weight > 0),
        key=lambda pair: pair[0],
    )

    threshold = total / 2 - 1e-9
    cumulative = 0.0

    for value, weight in pairs:
        cumulative += weight
        if cumulative >= threshold:
            return value

    # Defensive fallback for floating-point accumulation.
    return pairs[-1][0]

