def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be at least 1")

    chosen: list[int] = []  # Min-heap of selected bounties
    total = 0

    for deadline, bounty in sorted(jobs, key=itemgetter(0)):
        capacity = cap * deadline

        if len(chosen) < capacity:
            heappush(chosen, bounty)
            total += bounty
        elif bounty > chosen[0]:
            total += bounty - heapreplace(chosen, bounty)

    return total

def count_dominant_pairs(seq: list[int]) -> int:
    n = len(seq)
    if n < 2:
        return 0

    a = seq.copy()
    temp = [0] * n

    def sort_and_count(lo: int, hi: int) -> int:
        if hi - lo < 2:
            return 0

        mid = (lo + hi) // 2
        count = sort_and_count(lo, mid) + sort_and_count(mid, hi)

        # Both halves are now sorted. Count pairs spanning the halves.
        j = mid
        for i in range(lo, mid):
            while j < hi and a[i] > 3 * a[j]:
                j += 1
            count += j - mid

        # Merge the sorted halves.
        i, j, k = lo, mid, lo
        while i < mid and j < hi:
            if a[i] <= a[j]:
                temp[k] = a[i]
                i += 1
            else:
                temp[k] = a[j]
                j += 1
            k += 1

        while i < mid:
            temp[k] = a[i]
            i += 1
            k += 1

        while j < hi:
            temp[k] = a[j]
            j += 1
            k += 1

        a[lo:hi] = temp[lo:hi]
        return count

    return sort_and_count(0, n)

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}

    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i}: expected a tuple of exactly 3 elements")

        category, amount, refunded = row

        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i}: category must be a non-empty str")

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}: amount must be an int or float, not bool")

        if amount < 0:
            raise ValueError(f"row {i}: amount must be non-negative")

        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}: refunded must be a bool")

        value = float(amount)

        if category not in result:
            result[category] = {
                "count": 1,
                "gross": value,
                "net": 0.0 if refunded else value,
                "largest": value,
            }
        else:
            summary = result[category]
            summary["count"] += 1
            summary["gross"] += value
            if not refunded:
                summary["net"] += value
            if value > summary["largest"]:
                summary["largest"] = value

    return result

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    if (
        isinstance(low, bool)
        or isinstance(high, bool)
        or not isinstance(low, (int, float))
        or not isinstance(high, (int, float))
    ):
        raise TypeError("bounds must be numbers")

    if low > high:
        raise ValueError("low must not exceed high")

    # Validate all elements before performing any element comparisons.
    for i, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"invalid number at index {i}")

    result = []
    for value in values:
        if value < low:
            result.append(low)
        elif value > high:
            result.append(high)
        else:
            result.append(value)

    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    stack = [(iter(nested), max_depth)]

    while stack:
        iterator, remaining_depth = stack[-1]

        try:
            item = next(iterator)
        except StopIteration:
            stack.pop()
            continue

        if isinstance(item, list) and remaining_depth > 0:
            stack.append((iter(item), remaining_depth - 1))
        else:
            result.append(item)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")

    if not text or text.isspace():
        raise ValueError("empty duration")

    units = {"h": (0, 3600), "m": (1, 60), "s": (2, 1)}
    total = 0
    last_rank = -1
    i = 0
    n = len(text)

    while i < n:
        if not ("0" <= text[i] <= "9"):
            raise ValueError("malformed duration")

        value = 0
        while i < n and "0" <= text[i] <= "9":
            value = value * 10 + (ord(text[i]) - 48)
            i += 1

        if i == n or text[i] not in units:
            raise ValueError("malformed duration")

        rank, multiplier = units[text[i]]
        if rank <= last_rank:
            raise ValueError("malformed duration")

        total += value * multiplier
        last_rank = rank
        i += 1

    return total

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    output = []
    i = 0
    n = len(template)

    while i < n:
        char = template[i]

        if char == "{":
            if i + 1 < n and template[i + 1] == "{":
                output.append("{")
                i += 2
                continue

            start = i
            i += 1
            name_start = i

            while i < n and template[i] != "}":
                c = template[i]
                if not (
                    "A" <= c <= "Z"
                    or "a" <= c <= "z"
                    or "0" <= c <= "9"
                    or c == "_"
                ):
                    raise ValueError(
                        f"invalid placeholder at position {start}"
                    )
                i += 1

            if i == n:
                raise ValueError(
                    f"unclosed placeholder at position {start}"
                )

            if i == name_start:
                raise ValueError(
                    f"empty placeholder at position {start}"
                )

            name = template[name_start:i]
            if name not in context:
                raise KeyError(name)

            output.append(str(context[name]))
            i += 1

        elif char == "}":
            if i + 1 < n and template[i + 1] == "}":
                output.append("}")
                i += 2
            else:
                raise ValueError(f"stray '}}' at position {i}")

        else:
            output.append(char)
            i += 1

    return "".join(output)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if not tokens:
        raise ValueError("empty expression")

    stack = []

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError(f"token {i} must be a str")

        if token in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")

            right = stack.pop()
            left = stack.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                result = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    result = -result

            stack.append(result)
            continue

        start = 1 if token[:1] in ("+", "-") else 0
        if start == len(token):
            raise ValueError(f"unknown token at token {i}")

        # Parse manually to avoid limits on converting very long strings to int.
        value = 0
        for char in token[start:]:
            if not ("0" <= char <= "9"):
                raise ValueError(f"unknown token at token {i}")
            value = value * 10 + (ord(char) - ord("0"))

        if token[:1] == "-":
            value = -value
        stack.append(value)

    if len(stack) > 1:
        raise ValueError("leftover operands")

    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment")

    def descend(node, position):
        if position == len(segments):
            return node

        segment = segments[position]

        if isinstance(node, dict):
            child = node[segment]

        elif isinstance(node, list):
            digits = segment[1:] if segment.startswith("-") else segment
            if not digits or not digits.isascii() or not digits.isdigit():
                raise ValueError(f"invalid index: {segment}")

            # Normalize leading zeros and reject enormous indices before int().
            normalized = digits.lstrip("0") or "0"
            if len(normalized) > len(str(len(node))):
                raise IndexError(f"index out of range: {segment}")

            index = int(normalized)
            if segment.startswith("-"):
                index = -index

            try:
                child = node[index]
            except IndexError:
                raise IndexError(f"index out of range: {segment}") from None

        else:
            raise TypeError(f"cannot descend through {type(node).__name__}")

        return descend(child, position + 1)

    return descend(data, 0)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0:
        return []

    counts = {}
    values = []
    for value in items:
        if value not in counts:
            counts[value] = 0
            values.append(value)
        counts[value] += 1

    result = []
    while values and len(result) < k:
        best_index = 0
        for index in range(1, len(values)):
            if counts[values[index]] > counts[values[best_index]]:
                best_index = index

        value = values.pop(best_index)
        result.append((value, counts[value]))

    return result
